-- Ensure launch-critical resource tables are tenant scoped through workspace membership.
do $$declare t text;begin foreach t in array array['projects','environments','validations','validation_steps','findings','usage_events','audit_events','workspace_plans'] loop if exists(select 1 from information_schema.columns where table_schema='public' and table_name=t and column_name='workspace_id') then execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists lythouse_launch_workspace_access on public.%I',t);execute format('create policy lythouse_launch_workspace_access on public.%I for all to authenticated using (public.is_workspace_member(workspace_id)) with check (public.is_workspace_member(workspace_id))',t);end if;end loop;end$$;